/** `socle.json`: the build base (tools/kit-modules/socle.mjs writes it). */
export interface KitSocle {
  schema: string;
  contract: string;
  rust: { toolchain: string; components: string[]; targets: string[] };
  profile: Record<string, string | number | boolean>;
  modes: Record<KitMode, { features: string[]; rustflags: string; cargoArgs: string[]; env: Record<string, string>; macros: string[]; contracts: string[]; envImports?: string[] }>;
  isolatedLinks: string[];
  structs: { version: string; structs: KitStruct[] };
  lockRoot: string;
  crates: Record<string, string>;
}

export interface KitSdk { root: string; guest: string; socle: KitSocle; lock: string; bundled: boolean }

const SOCLE_SCHEMA = 'gripforge.kit-socle/1';
const here = dirname(fileURLToPath(import.meta.url));
const sha256 = (bytes: Uint8Array) => createHash('sha256').update(bytes).digest('hex');
const KIT_ID = /^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$/;

/** The `kit-sdk` folder of the `gripforge` CLI found on PATH (how the MCP client, which ships none, finds it). */
function sdkOfCliOnPath(): string[] {
  const out: string[] = [];
  for (const dir of (process.env.PATH ?? '').split(delimiter).filter(Boolean)) {
    for (const name of ['gripforge', 'grip-forge']) {
      try { const bin = realpathSync(join(dir, name)); out.push(resolve(dirname(bin), '../kit-sdk')); } catch { /* not there */ }
    }
  }
  return out;
}

/**
 * The kit SDK: `dir` (or `GRIPFORGE_KIT_SDK`), else the one shipped in this package (`kit-sdk/`), else the GripForge
 * checkout this file lives in, else the one of the `gripforge` CLI on PATH. An SDK is a folder that holds
 * `native/gripforge-kit-guest/socle.json`.
 */
export function findKitSdk(dir?: string): KitSdk {
  const asked = dir ?? process.env.GRIPFORGE_KIT_SDK;
  const candidates = asked ? [resolve(asked)] : [resolve(here, '../kit-sdk'), resolve(here, '../../..'), ...sdkOfCliOnPath()];
  for (const root of candidates) {
    const guest = join(root, 'native/gripforge-kit-guest'), file = join(guest, 'socle.json');
    if (!existsSync(file)) continue;
    const socle = JSON.parse(readFileSync(file, 'utf8')) as KitSocle;
    if (socle.schema !== SOCLE_SCHEMA) throw Error(`${file}: build base of schema ${String(socle.schema)}, this CLI reads ${SOCLE_SCHEMA} — update the CLI (gripforge update) or pass the SDK of this CLI`);
    const lockFile = join(guest, 'socle.Cargo.lock');
    if (!existsSync(lockFile)) throw Error(`${lockFile}: the lock of the build base is missing — this kit SDK is incomplete`);
    return { root, guest, socle, lock: readFileSync(lockFile, 'utf8'), bundled: root === candidates[0] && !asked };
  }
  throw Error(asked
    ? `${resolve(asked)}: not a kit SDK (no native/gripforge-kit-guest/socle.json) — --sdk takes a GripForge checkout or the kit-sdk folder of the CLI`
    : 'the kit SDK was not found (it is shipped in the GripForge CLI, in its kit-sdk folder): install or update the CLI (gripforge update), or pass the kit SDK — or a GripForge checkout — with --sdk <folder> (or GRIPFORGE_KIT_SDK)');
}

export interface ToolchainReport { ok: boolean; toolchain: string; rustc: string | null; missing: string[]; install: string; installed: boolean }

/**
 * Whether the pinned toolchain of the base is there with its components and its target (asked of rustup). `install`:
 * what is missing is installed — `rustup toolchain install <pin> …`, which adds a toolchain beside the others and
 * changes neither the default one nor `stable`. Never throws for a missing piece: the report says what to run.
 */
export function checkToolchain(socle: KitSocle, options: { install?: boolean; env?: NodeJS.ProcessEnv; log?: (line: string) => void } = {}): ToolchainReport {
  const { toolchain, components, targets } = socle.rust, env = options.env ?? process.env;
  const install = `rustup toolchain install ${toolchain} --profile minimal --no-self-update${targets.map((t) => ` --target ${t}`).join('')}${components.map((c) => ` --component ${c}`).join('')}`;
  const rustup = (args: string[]) => spawnSync('rustup', args, { encoding: 'utf8', env });
  const probe = (): Omit<ToolchainReport, 'install' | 'installed'> => {
    const version = rustup(['--version']);
    if (version.error || version.status !== 0) return { ok: false, toolchain, rustc: null, missing: ['rustup (https://rustup.rs — the installer of Rust toolchains)'] };
    const list = rustup(['component', 'list', '--toolchain', toolchain, '--installed']);
    if (list.status !== 0) return { ok: false, toolchain, rustc: null, missing: [`the Rust toolchain ${toolchain}`] };
    const have = list.stdout.split('\n').map((l) => l.trim()).filter(Boolean);
    const missing = [
      ...components.filter((c) => !have.some((h) => h === c || h.startsWith(`${c}-`))).map((c) => `the component ${c} of the toolchain ${toolchain}`),
      ...targets.filter((t) => !have.includes(`rust-std-${t}`)).map((t) => `the target ${t} of the toolchain ${toolchain}`),
    ];
    const rustc = rustup(['run', toolchain, 'rustc', '-V']);
    return { ok: !missing.length && rustc.status === 0, toolchain, rustc: rustc.status === 0 ? rustc.stdout.trim() : null, missing };
  };
  let report = probe(), installed = false;
  if (!report.ok && options.install && !report.missing.some((m) => m.startsWith('rustup '))) {
    options.log?.(`installing the build base: ${install}`);
    const run = spawnSync('rustup', install.split(' ').slice(1), { stdio: ['ignore', 'inherit', 'inherit'], env });
    if (run.status !== 0) throw Error(`rustup could not install the build base (exit ${String(run.status)}): ${install}`);
    installed = true;
    report = probe();
  }
  return { ...report, install, installed };
}

/** The message of a toolchain that is not ready: what is missing, and the one command that installs it. */
export function toolchainRefusal(r: ToolchainReport): string {
  if (r.missing.some((m) => m.startsWith('rustup '))) return `gripforge kit build needs ${r.missing[0]}. Install rustup, then run: ${r.install}`;
  return `the build base needs ${r.missing.join(', ') || `a working rustc ${r.toolchain}`}. Install it (it is added beside your toolchains; the default one does not change):\n  ${r.install}\nor run the build again with --install`;
}

export interface KitSource { dir: string; manifestFile: string; manifest: ThirdPartyKitManifest & { source?: string; module?: string; crates?: Record<string, string> }; source: string; module: string; hooks: number; crates: Record<string, string> }

/** Reads the kit's folder: `kit.json`, its source file, the per-tick hooks it implements. Throws with every problem. */
export function readKitSource(folder: string): KitSource {
  const dir = resolve(folder);
  if (!existsSync(dir) || !statSync(dir).isDirectory()) throw Error(`${dir}: not a folder — gripforge kit build takes the folder of a kit (it holds kit.json and the kit's Rust source)`);
  const manifestFile = join(dir, 'kit.json');
  if (!existsSync(manifestFile)) throw Error(`${manifestFile}: not found — a kit folder holds kit.json: { "schema": "${THIRD_PARTY_KIT_SCHEMA}", "id": "acme.streak", "version": "1.0.0" } (guide: gripforge docs kit-third-party)`);
  let manifest: KitSource['manifest'];
  try { manifest = JSON.parse(readFileSync(manifestFile, 'utf8')) as KitSource['manifest']; } catch (error) { throw Error(`${manifestFile}: not JSON (${(error as Error).message})`); }
  const issues: string[] = [];
  if (!manifest || typeof manifest !== 'object' || Array.isArray(manifest)) throw Error(`${manifestFile}: not an object`);
  if (manifest.schema !== THIRD_PARTY_KIT_SCHEMA) issues.push(`kit.json: "schema" must be "${THIRD_PARTY_KIT_SCHEMA}" (got ${JSON.stringify(manifest.schema)})`);
  if (typeof manifest.id !== 'string' || !KIT_ID.test(manifest.id)) issues.push(`kit.json: "id" must be a dotted lowercase id of your own, like "acme.streak" (got ${JSON.stringify(manifest.id)})`);
  if (!parseKitVersion(manifest.version) || String(manifest.version).split('.').length !== 3) issues.push(`kit.json: "version" must be major.minor.patch (got ${JSON.stringify(manifest.version)})`);
  const rel = typeof manifest.source === 'string' && manifest.source ? manifest.source : 'src/lib.rs', source = resolve(dir, rel);
  if (isAbsolute(rel) || rel.split(/[\\/]/).includes('..')) issues.push(`kit.json: "source" must be a file inside the kit folder (got ${JSON.stringify(rel)})`);
  else if (!existsSync(source)) issues.push(`${source}: the kit's source is not there ("source" of kit.json, src/lib.rs by default)`);
  const module = typeof manifest.module === 'string' && manifest.module ? manifest.module : 'module';
  if (!/^[A-Za-z_][A-Za-z0-9_]*(::[A-Za-z_][A-Za-z0-9_]*)*$/.test(module)) issues.push(`kit.json: "module" must be the path of a function in the source, like "module" (got ${JSON.stringify(module)})`);
  const crates: Record<string, string> = {};
  for (const [name, version] of Object.entries(manifest.crates ?? {})) {
    if (!/^[A-Za-z0-9_-]+$/.test(name) || typeof version !== 'string' || !/^[0-9A-Za-z.^~=<>*, +-]+$/.test(version)) issues.push(`kit.json: crates.${name} must be a crate name and a version requirement, like "smallvec": "1" (a kit takes crates of crates.io only)`);
    else if (name === 'gripforge-kit-guest' || name === 'serde_json') issues.push(`kit.json: crates.${name} — the build base already gives this crate, at its own version`);
    else crates[name] = version;
  }
  if (issues.length) throw Error(issues.join('\n'));
  // Every Rust file of the folder (the source and what it includes): the hooks it implements, and misuse the tool can name.
  const files: string[] = [];
  const walk = (d: string) => { for (const n of readdirSync(d)) { if (n === 'target' || n === 'build' || n === 'node_modules' || n.startsWith('.')) continue; const p = join(d, n); if (statSync(p).isDirectory()) walk(p); else if (n.endsWith('.rs')) files.push(p); } };
  walk(dirname(source));
  const text = files.map((f) => readFileSync(f, 'utf8')).join('\n'), own = readFileSync(source, 'utf8');
  if (/\b(export_kit|isolated_kit|common_memory)!\s*\(/.test(text)) throw Error(`${source}: the source invokes an export macro (export_kit!, isolated_kit! or common_memory!) — remove it: gripforge kit build writes the crate and the exports of each mode around the source, which only gives "pub fn ${module}() -> Rc<dyn KitModule>"`);
  const leaf = module.split('::').pop()!;
  if (!new RegExp(`\\bpub(\\s*\\([^)]*\\))?\\s+fn\\s+${leaf}\\s*\\(`).test(text)) throw Error(`${source}: no "pub fn ${leaf}()" — the source gives the kit to the build tool by a public function: pub fn ${leaf}() -> std::rc::Rc<dyn gripforge_kit_guest::KitModule> ("module" of kit.json names another one)`);
  void own;
  const hooks = (/\bfn update\s*\(/.test(text) ? 1 : 0) | (/\bfn late_update\s*\(/.test(text) ? 2 : 0) | (/\bfn update_idle\s*\(/.test(text) ? 4 : 0);
  return { dir, manifestFile, manifest, source, module, hooks, crates };
}

export interface BuildKitOptions { kit: string; out?: string; mode?: KitMode | 'both'; sdk?: string; targetDir?: string; install?: boolean; jobs?: number; cwd?: string; quiet?: boolean; log?: (line: string) => void; env?: NodeJS.ProcessEnv }
export interface BuiltKit { mode: KitMode; wasm: string; manifest: string; sha256: string; bytes: number; structs: string; provides: string[]; consumes: string[] }
export interface BuildKitReport { id: string; version: string; kit: string; out: string; sdk: string; contract: string; structs: string; toolchain: string; rustc: string | null; hooks: number; crates: Record<string, string>; built: BuiltKit[]; warnings: string[] }

const toml = (v: string | number | boolean) => (typeof v === 'string' ? JSON.stringify(v) : String(v));

/**
 * Builds a kit on the build base. Throws an Error whose message names what stopped it — the toolchain (with the
 * command that installs it), the compiler's errors (shown as they come), or the binary that does not fit (which
 * check, expected / found).
 */
export function buildKit(options: BuildKitOptions): BuildKitReport {
  const cwd = options.cwd ?? process.cwd(), log = options.log ?? ((line: string) => { if (!options.quiet) console.error(line); });
  const src = readKitSource(isAbsolute(options.kit) ? options.kit : resolve(cwd, options.kit));
  const sdk = findKitSdk(options.sdk ? (isAbsolute(options.sdk) ? options.sdk : resolve(cwd, options.sdk)) : undefined), socle = sdk.socle;
  const which = options.mode ?? 'both';
  if (which !== 'both' && !(KIT_MODES as readonly string[]).includes(which)) throw Error(`--mode must be isolated, common or both (got ${String(which)})`);
  const modes: KitMode[] = which === 'both' ? [...KIT_MODES] : [which];
  const env = options.env ?? process.env;
  const toolchain = checkToolchain(socle, { install: options.install, env, log });
  if (!toolchain.ok) throw Error(toolchainRefusal(toolchain));
  const { id, version } = src.manifest, crate = `kit-${id.replace(/[._]/g, '-')}`, artifact = `${crate.replace(/-/g, '_')}.wasm`;
  const out = resolve(cwd, options.out ?? join(src.dir, 'build')), work = resolve(cwd, options.targetDir ?? join(src.dir, 'target/gripforge-kit'));
  mkdirSync(out, { recursive: true });
  const extra = Object.keys(src.crates).length > 0, warnings: string[] = [], built: BuiltKit[] = [];
  const write = (path: string, text: string) => { if (!existsSync(path) || readFileSync(path, 'utf8') !== text) writeFileSync(path, text); }; // keep cargo's fingerprints
  // Paths of this machine out of the binary (panic locations): the same source gives the same bytes anywhere.
  let sysroot = '', commit = '';
  try {
    sysroot = execFileSync('rustup', ['run', socle.rust.toolchain, 'rustc', '--print', 'sysroot'], { encoding: 'utf8', env }).trim();
    commit = /commit-hash: ([0-9a-f]+)/.exec(execFileSync('rustup', ['run', socle.rust.toolchain, 'rustc', '-vV'], { encoding: 'utf8', env }))?.[1] ?? '';
  } catch { /* the remap of the standard library is skipped */ }
  const cargoHome = env.CARGO_HOME ?? (env.HOME ? join(env.HOME, '.cargo') : '');
  const remap = [[sdk.root, '/gripforge-kit-sdk'], [src.dir, `/kit/${id}`], [work, '/build'], ...(cargoHome ? [[cargoHome, '/cargo']] : []), ...(sysroot && commit ? [[join(sysroot, 'lib/rustlib/src/rust'), `/rustc/${commit}`]] : [])]
    .map(([from, to]) => `--remap-path-prefix=${from}=${to}`).join(' ');

  for (const mode of modes) {
    const m = socle.modes[mode], dir = join(work, 'crates', id, mode);
    mkdirSync(join(dir, 'src'), { recursive: true });
    write(join(dir, 'Cargo.toml'), [
      `# Generated by gripforge kit build — the ${mode} build of ${id}@${version} on the build base ${socle.contract}.`,
      '[package]', `name = ${toml(crate)}`, `version = ${toml(version)}`, 'edition = "2021"', 'publish = false', '',
      '[lib]', 'crate-type = ["cdylib"]', 'path = "src/lib.rs"', '',
      '[dependencies]', `gripforge-kit-guest = { path = ${toml(sdk.guest)}, features = ${JSON.stringify(m.features)} }`, 'serde_json = { version = "1", features = ["preserve_order", "float_roundtrip"] }',
      ...Object.entries(src.crates).map(([name, req]) => `${name} = ${toml(req)}`), '',
      '[workspace]', '', '[profile.release]', ...Object.entries(socle.profile).map(([k, v]) => `${k} = ${toml(v)}`), '',
    ].join('\n'));
    const exports = mode === 'isolated'
      ? `gripforge_kit_guest::isolated_kit!(kit::${src.module}, ${toml(version)}, ${src.hooks});`
      : `gripforge_kit_guest::export_kit!(kit::${src.module}, ${toml(version)}, ${src.hooks});\ngripforge_kit_guest::common_memory!();`;
    write(join(dir, 'src/lib.rs'), `//! The kit module ${id}@${version}, ${mode} build (generated by gripforge kit build; the source is the kit's).\n#[path = ${toml(src.source)}]\nmod kit;\n\n${exports}\n`);
    // The lock of the base, with this crate as its root. With crates of its own the kit resolves them on top of it.
    const lockFile = join(dir, 'Cargo.lock');
    const seeded = sdk.lock.replace(`name = "${socle.lockRoot}"\nversion = "0.0.0"`, `name = "${crate}"\nversion = "${version}"`);
    if (!extra || !existsSync(lockFile)) write(lockFile, seeded);
    const args = ['run', socle.rust.toolchain, 'cargo', 'build', '--release', '--target', socle.rust.targets[0]!, ...(extra ? [] : ['--locked']), ...(options.jobs ? ['-j', String(options.jobs)] : []), ...m.cargoArgs];
    const target = join(work, mode);
    log(`building ${id}@${version} (${mode}) with Rust ${socle.rust.toolchain}…`);
    const run = spawnSync('rustup', args, { cwd: dir, stdio: ['ignore', options.quiet ? 'pipe' : 2, options.quiet ? 'pipe' : 2], encoding: 'utf8', env: { ...env, ...m.env, RUSTFLAGS: `${m.rustflags} ${remap}`.trim(), CARGO_TARGET_DIR: target, RUSTUP_TOOLCHAIN: socle.rust.toolchain } });
    if (run.status !== 0) throw Error(`${id}@${version} (${mode}): the build failed (cargo exit ${String(run.status)})${options.quiet && run.stderr ? `\n${String(run.stderr).trim().split('\n').slice(-40).join('\n')}` : ' — the compiler\'s errors are above'}${extra ? '' : '\n(the crates are locked to the build base: a crate the kit needs goes in "crates" of kit.json)'}`);
    const file = join(target, socle.rust.targets[0]!, 'release', artifact);
    if (!existsSync(file)) throw Error(`${id}@${version} (${mode}): cargo built nothing at ${file}`);
    const bytes = readFileSync(file);

    // The binary against the base: its mode, its structures, what it links.
    const info = inspectKitWasm(bytes), found = kitBinaryMode(info), problems: string[] = [];
    if (found !== mode) problems.push(`expected a ${mode} kit module, found ${found ?? 'a module that is neither relocatable nor isolated'}`);
    const structs = kitStructsMismatch(socle.structs, info.structs, 'the build base');
    if (structs) problems.push(structs);
    const lines = (kind: string) => info.contracts.filter((l) => l.startsWith(`${kind} `)).map((l) => l.slice(kind.length + 1).trim());
    const wanted = [...m.contracts].sort(), got = [...info.contracts].sort();
    if (JSON.stringify(wanted) !== JSON.stringify(got)) problems.push(`contracts: expected [${wanted.join('; ')}], found [${got.join('; ')}]`);
    if (mode === 'isolated') {
      for (const i of info.imports) {
        if (i.module.startsWith('gf:') && !socle.isolatedLinks.includes(i.name)) problems.push(`it links ${i.module}/${i.name}, which an isolated kit module may not take (it is not a link that carries numbers only)`);
        else if (!i.module.startsWith('gf:') && i.module !== 'gf_calls') problems.push(`it imports ${i.module}.${i.name}, which no host gives a kit module (a crate of the kit asks for the system: file, clock, random…)`);
      }
    } else {
      for (const i of info.imports) if (!i.module.startsWith('gf:') && i.module !== 'gf_calls' && !(i.module === 'env' && (m.envImports ?? []).includes(i.name))) problems.push(`it imports ${i.module}.${i.name}, which no host gives a kit module${i.module.startsWith('GOT.') ? ' (a symbol left for a dynamic linker: the address of an imported function was taken)' : ''}`);
    }
    // The crates of the base at the versions of the base (a kit with crates of its own may have moved one).
    if (extra && existsSync(lockFile)) {
      const lock = readFileSync(lockFile, 'utf8');
      for (const [name, want] of Object.entries(socle.crates)) {
        const have = [...lock.matchAll(new RegExp(`name = "${name}"\\nversion = "([^"]+)"`, 'g'))].map((x) => x[1]!);
        if (have.length && !have.includes(want)) problems.push(`crate ${name}: expected ${want} (the build base), found ${have.join(', ')} — a crate of the kit asks for another version; the values of the kit must be computed by the versions of the base`);
      }
    }
    if (problems.length) throw Error(`${id}@${version} (${mode}): the binary does not fit the build base —\n  ${problems.join('\n  ')}`);

    const digest = sha256(bytes), name = `${id}-${version}.${mode}`;
    const { source: _source, module: _module, crates: _crates, wasm: _w, sha256: _s, bytes: _b, built: _built, memory: _m, structs: _st, provides: _p, consumes: _c, ...authored } = src.manifest;
    const manifest: ThirdPartyKitManifest = {
      ...authored, schema: THIRD_PARTY_KIT_SCHEMA, id, version,
      provides: lines('provides'), consumes: lines('consumes'),
      memory: mode, structs: socle.structs.version, wasm: `${name}.wasm`, sha256: digest, bytes: bytes.length,
      built: { by: 'gripforge kit build', base: socle.schema, contract: socle.contract, toolchain: socle.rust.toolchain, rustc: toolchain.rustc, hooks: src.hooks, ...(extra ? { crates: src.crates } : {}) },
    };
    const check = checkThirdPartyKit({ manifest, wasm: bytes, structs: socle.structs, trust: mode });
    if (check.issues.length) throw Error(`${id}@${version} (${mode}): ${check.issues.join('\n')}`);
    warnings.push(...check.warnings);
    writeFileSync(join(out, `${name}.wasm`), bytes);
    writeFileSync(join(out, `${name}.kit.json`), `${JSON.stringify(manifest, null, 2)}\n`);
    built.push({ mode, wasm: join(out, `${name}.wasm`), manifest: join(out, `${name}.kit.json`), sha256: digest, bytes: bytes.length, structs: socle.structs.version, provides: manifest.provides, consumes: manifest.consumes });
  }
  const report: BuildKitReport = { id, version, kit: src.dir, out, sdk: sdk.root, contract: socle.contract, structs: socle.structs.version, toolchain: socle.rust.toolchain, rustc: toolchain.rustc, hooks: src.hooks, crates: src.crates, built, warnings };
  writeFileSync(join(out, 'build.json'), `${JSON.stringify({ schema: 'gripforge.kit-build/1', id, version, contract: socle.contract, structs: socle.structs.version, toolchain: socle.rust.toolchain, rustc: toolchain.rustc, builds: Object.fromEntries(built.map((b) => [b.mode, { wasm: `${id}-${version}.${b.mode}.wasm`, manifest: `${id}-${version}.${b.mode}.kit.json`, sha256: b.sha256, bytes: b.bytes }])) }, null, 2)}\n`);
  return report;
}

/** What `gripforge kit build` prints. */
export function buildSummary(r: BuildKitReport): string {
  const lines = [`Built ${r.id}@${r.version} on the build base ${r.contract} (structures ${r.structs}, ${r.rustc ?? `Rust ${r.toolchain}`})`];
  for (const b of r.built) lines.push(`  ${b.mode.padEnd(8)} ${b.wasm}`, `           sha256 ${b.sha256}  (${b.bytes} bytes)`, `           manifest ${b.manifest}`);
  for (const w of r.warnings) lines.push(`  warning: ${w}`);
  lines.push('', 'Declare it in a game (its lock freezes the version, the sha256 and the trust):',
    `  gripforge kit add <game> --kit ${r.out}                    isolated: the kit keeps a memory of its own (the default)`,
    `  gripforge kit add <game> --kit ${r.out} --trust common     in the common memory: faster, and it can corrupt the game — only a kit you trust`,
    `Check a build against the core of a game: gripforge kit verify --kit ${r.out} --modules <folder of kit modules>`);
  return lines.join('\n');
}

/** What `gripforge kit socle` prints: the build base of this CLI. */
export function socleSummary(sdk: KitSdk, toolchain: ToolchainReport): string {
  const s = sdk.socle;
  return [`Build base of the kit logic modules (${sdk.bundled ? 'shipped in this CLI' : 'kit SDK'}: ${sdk.root})`,
    `  contract    ${s.contract}, structures ${s.structs.version} (${s.structs.structs.length} structures: gripforge docs kit-structures)`,
    `  toolchain   Rust ${s.rust.toolchain} + ${[...s.rust.components, ...s.rust.targets].join(', ')}  ${toolchain.ok ? `— ready (${toolchain.rustc})` : `— NOT READY: ${toolchain.missing.join(', ')}`}`,
    ...(toolchain.ok ? [] : [`              ${toolchain.install}`]),
    `  profile     ${Object.entries(s.profile).map(([k, v]) => `${k}=${String(v)}`).join(' ')}`,
    `  isolated    features ${s.modes.isolated.features.join(',')}; ${s.isolatedLinks.length} links allowed (numbers only)`,
    `  common      features ${s.modes.common.features.join(',')}; RUSTFLAGS ${s.modes.common.rustflags}; cargo ${s.modes.common.cargoArgs.join(' ')}`,
    `  crates      ${Object.entries(s.crates).map(([k, v]) => `${k} ${v}`).join(', ')}`].join('\n');
}
